"""Offline SVG viewer: display the four continuation measurements for one pole and source frame. Colors are graph data; signed weights belong to ordered star observations, not globally directed graph edges."""
from pathlib import Path
import json,re
H=Path(__file__).resolve().parents[1];D=H/'results'
g=json.loads((D/'ramsey_37_dual_stars.json').read_text()); observations=json.loads((D/'ramsey_37_ordered_star_sign.json').read_text()); base=(D/'ramsey_37_flat_frames.html').read_text(encoding='utf8'); svg=base[base.index('<svg '):base.index('</svg>')+6];E={tuple(e) for e in g['red_edges']}
assert all(len([a for a in observations if a['pole']==pole and a['source']==i])==4 for pole in ('pole0','pole6') for i in range(5));assert all(a['support'][1]-a['support'][0]==a['change'] and (tuple(sorted((a['slot'],a['continuation']))) in E)==a['red'] for a in observations)
svg=re.sub(r'<path class="wire".*?</path>','',svg);svg=svg.replace('<g class="node"','<g id="arrows"></g><g class="node"',1);svg=svg.replace('</svg>','<defs>'+''.join(f'<marker id="tip{c}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0L10 5L0 10Z" fill="{color}"/></marker>' for c,color in [('R','#b43226'),('B','#2469a2')])+'</defs></svg>')
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>22 positions | weighted continuations</title><style>*{box-sizing:border-box}body{font:16px system-ui;color:#172635;background:#fafafa;margin:1rem auto;max-width:1000px;padding:0 1rem}h1{font-size:1.55rem}.controls{display:flex;gap:.65rem;flex-wrap:wrap;align-items:center}button,select{font:inherit;padding:.25rem}svg{width:100%;max-height:65vh;background:white;border:1px solid #ddd}.frame{text-anchor:middle;fill:#617181;font-size:14px}.node circle{fill:#fff;stroke:#85929b}.node text{text-anchor:middle;font:bold 12px system-ui}.active circle{fill:#ffdf83;stroke:#634900}.pole circle{fill:#c4e6d7}.w{paint-order:stroke;stroke:white;stroke-width:5px;fill:#162634;font:bold 15px system-ui}.edge{cursor:pointer}td,th{padding:.25rem .65rem;text-align:left}tr.selected{background:#fff0be}p{max-width:80ch}</style><h1>Five frames · weighted continuation arrows</h1><p>Each arrow advances one tick from a slot to its copy in the next frame. Its label is the change in overlap between the two stars at the starting slot, measured from the other pole. Solid red and dashed blue are actual edge colors, not weight signs.</p><div class="controls"><label>Pole <select id="pole"><option value="pole0">P</option><option value="pole6">Q</option></select></label><label>Source frame <select id="frame">'''+''.join(f'<option>{i}</option>' for i in range(5))+'''</select></label><button id="next">Advance one tick</button><button id="rev">Reflect viewpoint</button><button id="reset">Show all four</button></div>'''+svg+'''<table><thead><tr><th>Local slot</th><th>Continuation</th><th>Overlap</th><th>Weight</th><th>Edge</th></tr></thead><tbody></tbody></table><p>Click an arrow or table row to isolate it. The pale diamonds are layout guides; not every Ramsey edge carries a weight.</p><script>const data=DATA; const $=x=>document.querySelector(x),el=(tag,attrs)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n};const nodes=new Map([...document.querySelectorAll('.node')].map(n=>[+n.dataset.id,n]));const xy=id=>{let p=nodes.get(id).transform.baseVal.getItem(0).matrix;return [p.e,p.f]},name=id=>nodes.get(id).textContent;let focus=null;const sign=n=>n>0?'+'+n:''+n;function draw(){let pole=$('#pole').value,i=+$('#frame').value,rows=data.filter(a=>a.pole===pole&&a.source===i),ar=$('#arrows'),tb=$('tbody');ar.replaceChildren();tb.replaceChildren();for(let [v,n] of nodes){n.classList.toggle('active',rows.some(a=>a.slot===v&&(focus===null||focus===a.slot)));n.classList.toggle('pole',v===(pole==='pole0'?0:6))}for(let [idx,a] of rows.entries()){let tr=tb.insertRow();tr.classList.toggle('selected',focus===a.slot);for(let v of [sign(a.local_step),name(a.slot)+' → '+name(a.continuation),a.support.join(' → '),sign(a.change),a.red?'red':'blue'])tr.insertCell().textContent=v;let pick=()=>{focus=focus===a.slot?null:a.slot;draw()};tr.onclick=pick;if(focus!==null&&focus!==a.slot)continue;let [x,y]=xy(a.slot),[u,v]=xy(a.continuation),L=Math.hypot(u-x,v-y),dx=(u-x)/L,dy=(v-y)/L,bend=(idx-1.5)*23,c=(x+u)/2-dy*bend,d=(y+v)/2+dx*bend,color=a.red?'#b43226':'#2469a2';let path=el('path',{class:'edge',d:`M${x+17*dx} ${y+17*dy} Q${c} ${d} ${u-18*dx} ${v-18*dy}`,fill:'none',stroke:color,'stroke-width':3,'stroke-dasharray':a.red?'none':'7 4','marker-end':`url(#tip${a.red?'R':'B'})`});path.onclick=pick;ar.append(path);let label=el('text',{class:'w',x:(x+u+2*c)/4,y:(y+v+2*d)/4-4});label.textContent=sign(a.change);label.onclick=pick;ar.append(label)}}function clear(){focus=null;draw()}$('#pole').onchange=$('#frame').onchange=$('#reset').onclick=clear;$('#next').onclick=()=>{$('#frame').value=(+$('#frame').value+($('#pole').value==='pole0'?1:4))%5;clear()};$('#rev').onclick=()=>{$('#pole').value=$('#pole').value==='pole0'?'pole6':'pole0';$('#frame').value=(5-Number($('#frame').value))%5;clear()};draw()</script>''';(D/'ramsey_37_weighted_arrows.html').write_text(html.replace('const data=DATA','const data='+json.dumps(observations)),encoding='utf8');print('Verified 40 colored, signed transitions and generated offline viewer.')
